using System.Text.Json.Serialization;
using Paid.Core.Models;

namespace Paid.Models;

public record TokenUsage
{
    /// <summary>
    /// Non-cached input tokens. Matches Anthropic's <c>input_tokens</c> semantic (does not include cached or cache-creation tokens).
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("inputTokens")]
    public int? InputTokens { get; init; }

    /// <summary>
    /// Output tokens generated by the model.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("outputTokens")]
    public int? OutputTokens { get; init; }

    /// <summary>
    /// Input tokens served from cache (cache hit).
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cacheReadInputTokens")]
    public int? CacheReadInputTokens { get; init; }

    /// <summary>
    /// Input tokens written to cache on this request (Anthropic prompt caching).
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cacheCreationInputTokens")]
    public int? CacheCreationInputTokens { get; init; }

    /// <summary>
    /// Reasoning tokens emitted by reasoning models (o1/o3, Claude extended thinking).
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("reasoningOutputTokens")]
    public int? ReasoningOutputTokens { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
